const body = $input.body || {};
const quantityNumber = Number(String(body.quantity || '').replace(/[^0-9.]/g, ''));
const isValid = Number.isFinite(quantityNumber) && quantityNumber > 0 && quantityNumber <= 10000;
return {
  isValid: isValid,
  quantityNumber: isValid ? quantityNumber : 0,
  materialName: String(body.materialName || '').trim(),
  siteEntityId: String(body.siteEntityId || ''),
  phoneNumber: String(body.phoneNumber || ''),
  requestorName: String(body.requestorName || ''),
  requestNumber: 'MR-' + String(body.flowTrackingId || '').slice(-8).toUpperCase()
};

