const r = $("get_site");
const envelope = (r && r.data) || r || {};
if (envelope.success === false || !envelope.entity) {
  return { siteFound: false, approverPhone: '', siteName: '' };
}
const site = envelope.entity.data || {};
return {
  siteFound: true,
  approverPhone: String(site.approverPhone || ''),
  siteName: String(site.siteName || '')
};

const r = $("create_request");
const envelope = (r && r.data) || r || {};
return {
  created: envelope.success === true && !!envelope.entityId,
  entityId: String(envelope.entityId || ''),
  createError: String(envelope.error || '')
};

// A $ reference must be the WHOLE string — "Request $x saved" is a literal, never interpolated.
// So any composite message is assembled here and referenced as one value by the send node.
const parsed = $("parse_and_validate") || {};
const site = $("read_site") || {};
return {
  text: 'Request ' + (parsed.requestNumber || '') + ' for ' +
        (parsed.quantityNumber || '') + ' x ' + (parsed.materialName || '') +
        ' has been sent for approval' + (site.siteName ? ' at ' + site.siteName : '') + '.'
};

