const parsed = $("parse_and_validate") || {};
if (!parsed.isValid) {
  return {
    success: false,
    message: 'Quantity must be a number between 1 and 10000. Please send the quantity again.',
    stateParams: { requestEntityId: '', requestNumber: '', approverPhone: '' }
  };
}
const createCheck = $("check_create") || {};
const site = $("read_site") || {};
if (!createCheck.created) {
  return {
    success: false,
    message: 'Sorry, we could not save your request right now. Please try again.',
    stateParams: { requestEntityId: '', requestNumber: '', approverPhone: '' }
  };
}
return {
  success: true,
  message: 'Material request ' + parsed.requestNumber + ' saved.',
  stateParams: {
    requestEntityId: createCheck.entityId,
    requestNumber: parsed.requestNumber,
    approverPhone: site.approverPhone || ''
  }
};
